	Light_Functions lgt_2;

	uint8 Pwm_Percentage = 0;
	uint8 Pixel_Unit=1;
	uint8 Total_Units=0;
	uint16 Channel_Mask=0;

	uint8 i=0;
	uint8 j=0;
