	uint8 j=0;
	uint8 k=0;

	float x1=gs_Dynamic_Light_Pattern_Execute_Info.Light_Pattern_OffsTiPrm_t;
	float x2=gs_Dynamic_Light_Pattern_Execute_Info.Light_Pattern_ContTiPrm_t;
	float y1=gs_Dynamic_Light_Pattern_Execute_Info.Light_Pattern_LowBriPrm_t;
	float y2=gs_Dynamic_Light_Pattern_Execute_Info.Light_Pattern_UpperBriPrm_t;
	float TimeCount = gs_Dynamic_Light_Pattern_Execute_Info.Light_Pattern_TimeCount[Group];

	float pulse=0;
	float t=0;

