				break;
			case MODE_6_Outward_Wiping_On:
				MODE_6_Outward_Wiping_On_Execute(Group);
				break;
			case MODE_7_Inward_Wiping_On:
				MODE_7_Inward_Wiping_On_Execute(Group);
