static void Dynamic_Charging_Control_Turn_OFF(Light_Functions lgt)
{
	S_LF_Info_T s_LF_Info;
	uint8 pixel_ID[12];
	uint16 Channel_Mask=0;
	uint8 i=0;
	uint8 j=0;
	uint8 Pwm_Percentage=0;

	lampM_GetLampInfo(lgt, &s_LF_Info);

	/*设置通道或者像素亮度*/
	for(i=0;i<12;i++)
	{
		if((s_LF_Info.chnMask) & (0x0001 << i))
		{
			/*Channel*/
			Channel_Mask=0;
			Channel_Mask |= (1<<i);
			LampM_SetLampChn(lgt, Channel_Mask, Pwm_Percentage, 0, 0);
		}
	}

}

static void Dynamic_PositionLight_Turn_ON_Interface(void)
{
	if((gs_Dynamic_Function_State_Info[LIGHT_Welcome_ID].LightState==OFF_Sts)
	&&(gs_Dynamic_Function_State_Info[LIGHT_Car_Approach_ID].LightState==OFF_Sts)
	&&(gs_Dynamic_Function_State_Info[LIGHT_HomeSafety_ID].LightState==OFF_Sts)
	&&(gs_Dynamic_Function_State_Info[LIGHT_Car_Locator_ID].LightState==OFF_Sts)
	&&(gs_Dynamic_Function_State_Info[LIGHT_Goodbye_ID].LightState==OFF_Sts)
	&&(gs_Dynamic_Function_State_Info[LIGHT_Light_Show_Control_ID].LightState==OFF_Sts)
	&&(gs_Dynamic_Function_State_Info[LIGHT_WaitMode_ID].LightState==OFF_Sts))
	{
		if(gs_Dynamic_Function_State_Info[LIGHT_Charging_PositionLight_ID].LightState == OFF_Sts)
		{
			gs_Dynamic_Function_State_Info[LIGHT_Charging_PositionLight_ID].LightState = ON_Sts;
			gs_Dynamic_Charging_Execute_Info.Charging_PositionLight_Step=0;
			gs_Dynamic_Charging_Execute_Info.Charging_PositionLight_TimeCount=Dynamic_Charging_Cycle;
			gs_Dynamic_Charging_Execute_Info.Charging_PositionLight_PWM_Value=0;
		}
		SetLgtStsFb_POS(STS_ON);
		Dynamic_Charging_Control_Turn_ON(E_PositionLight);
	}
	else
	{
		if(gs_Dynamic_Function_State_Info[LIGHT_Charging_PositionLight_ID].LightState == ON_Sts)
		{
			gs_Dynamic_Function_State_Info[LIGHT_Charging_PositionLight_ID].LightState = OFF_Sts;
			SetLgtStsFb_POS(STS_OFF);
			gs_Dynamic_Charging_Execute_Info.Charging_PositionLight_PWM_Value=0;
		}
	}

}

