void Dynamic_Light_Function_MainFunction(uint8 timebase)
{
	Dynamic_Light_Function_Priority();

	Welcome_Pattern_Download_Store_Retrieve_MainFunction();

	Light_Pattern_MainFunction();

	Exterior_Light_Show_MainFunction();

	Dynamic_Light_Function_Tick(timebase);

	
}

void Dynamic_Charging_Light_MainFunction(uint8 timebase)
{
	S_LgtActIns_t act;
	S_LgtFuncEna_t ena;

	GetLgtActIns(&act);
	GetLgtFuncEna(&ena);

	uint32_t IndcrSignalValue=0;
	Interface_GetSignal_IndcrSts(&IndcrSignalValue);
	uint32_t DRLSignalValue=0;
	Interface_GetSignal_ActnOfLedDaytiRunngLamp(&DRLSignalValue);

	uint32_t PositionLightSignalValue=0;
	Interface_GetSignal_ActnOfLedPosnLamp(&PositionLightSignalValue);
	uint32_t GrilleLampSignalValue=0;
	Interface_GetSignal_ActnOfLedGrilleLamp(&GrilleLampSignalValue);
	uint32_t LogoLampSignalValue=0;
    #if HCM_LEFT_SIDE
	Interface_GetSignal_ActnOfLedLeLogoLamp(&LogoLampSignalValue);
    #else
    Interface_GetSignal_ActnOfLedRiLogoLamp(&LogoLampSignalValue);
    #endif
	uint32_t FrontCrossLampSignalValue=0;
	Interface_GetSignal_ActnOfLedFrntCrossLamp(&FrontCrossLampSignalValue);

	if((gs_Dynamic_Function_Signal_Info.Welcome_Pattern_Actvn_Signal == ON_Welcome_Pattern)
	||(gs_Dynamic_Function_Signal_Info.Car_Approach_Pattern_Actvn_Signal == ON_CarApproach)
	||(gs_Dynamic_Function_Signal_Info.HomeSafety_Pattern_Actvn_Signal == ON_HomeSafety)
	||(gs_Dynamic_Function_Signal_Info.Car_Locator_Pattern_Actvn_Signal == ON_Locator_Pattern)
	||(gs_Dynamic_Function_Signal_Info.Goodbye_Pattern_Actvn_Signal == ON_Goodbye_Pattern)
	||(gs_Dynamic_Function_Signal_Info.ExtrLiShowActvnReq_Signal == Actvn_OnOff1_On)
	||(gs_Dynamic_Function_Signal_Info.Waitmode_Pattern_Actvn_Signal == ON_Waitmode))
	{
		Dynamic_PositionLight_Turn_OFF_Interface();
		
		Dynamic_GrilleLamp_Turn_OFF_Interface();
		
		Dynamic_LogoLamp_Turn_OFF_Interface();
		
		Dynamic_FrontCrossLamp_Turn_OFF_Interface();
		
	}
	else
	{
		if((act.ActPOS_Dyn==ACT_ON)&&(ena.EnaPOS_Dyn==ENA_ON)&&(IndcrSignalValue==ACT_OFF)&&(DRLSignalValue==ACT_OFF))
		{
			if(PositionLightSignalValue==0)
			{
				Dynamic_PositionLight_Turn_ON_Interface();
			}
			else
			{
				Dynamic_PositionLight_Turn_OFF_Interface();
			}
		}
		else
		{
			Dynamic_PositionLight_Turn_OFF_Interface();
		}
		if((act.ActGRIL_Dyn==ACT_ON)&&(ena.EnaGRIL_Dyn==ENA_ON))
		{
			if(GrilleLampSignalValue==0)
			{
				Dynamic_GrilleLamp_Turn_ON_Interface();
			}
			else
			{
				Dynamic_GrilleLamp_Turn_OFF_Interface();
			}
		}
		else
		{
			Dynamic_GrilleLamp_Turn_OFF_Interface();
		}
		if((act.ActLOGO_Dyn==ACT_ON)&&(ena.EnaLOGO_Dyn==ENA_ON))
		{
			if(LogoLampSignalValue==0)
			{
				Dynamic_LogoLamp_Turn_ON_Interface();
			}
			else
			{
				Dynamic_LogoLamp_Turn_OFF_Interface();
			}
		}
		else
		{
			Dynamic_LogoLamp_Turn_OFF_Interface();
		}
		if((act.ActCROS_Dyn==ACT_ON)&&(ena.EnaCROS_Dyn==ENA_ON))
		{
			if(FrontCrossLampSignalValue==0)
			{
				Dynamic_FrontCrossLamp_Turn_ON_Interface();
			}
			else
			{
				Dynamic_FrontCrossLamp_Turn_OFF_Interface();
			}
		}
		else
		{
			Dynamic_FrontCrossLamp_Turn_OFF_Interface();
		}
	}
}

uint8 Interface_Store_ModeReq_Signal(void)
{
	uint8 Store_Finish_Status=E_OK;

	Interface_EraseMemory(E_MemoryType_WelGby);
	Store_Finish_Status |= Interface_WriteMemory(E_MemoryType_WelGby, 
												Welcome_Pattern_Execute_Info_Total_Size, 
												&gs_Dynamic_Light_Pattern_Welcome_Parameters_Info);
	return Store_Finish_Status;
}

S_Dynamic_Function_State_Info* GetDynamicLightFunctionStateInfo(uint8 Dynamic_Light_Function_id)
{
	uint8 i=0;
	for(i=0;i<LIGHT_Function_Total_ID;i++)
	{
		if(Dynamic_Light_Function_id == gs_Dynamic_Function_State_Info[i].LightID)
		{
			return &gs_Dynamic_Function_State_Info[i];
		}
	}
	return NULL;
}

uint8 Interface_Dynamic_Light_Execute_Status(void)
{
	uint8 i=0;
	uint8 Result=0;
	for(i=0;i<LIGHT_Function_Total_ID;i++)
	{
		if(gs_Dynamic_Function_State_Info[i].LightState==ON_Sts)
		{
			if((gs_Dynamic_Function_State_Info[i].LightID==LIGHT_Welcome_ID)
			||(gs_Dynamic_Function_State_Info[i].LightID==LIGHT_Goodbye_ID)
			||(gs_Dynamic_Function_State_Info[i].LightID==LIGHT_WaitMode_ID)
			||(gs_Dynamic_Function_State_Info[i].LightID==LIGHT_Car_Approach_ID)
			||(gs_Dynamic_Function_State_Info[i].LightID==LIGHT_HomeSafety_ID)
			||(gs_Dynamic_Function_State_Info[i].LightID==LIGHT_Car_Locator_ID)
			||(gs_Dynamic_Function_State_Info[i].LightID==LIGHT_Light_Show_Control_ID))
			{
				Result=1;
				return Result;
			}
		}
	}
	return Result;
}

